import { MinHeap } from './heap.mjs';

export function comparePaths(p, q) {
  const n = Math.min(p.length, q.length);
  for (let i = 0; i < n; i++) {
    if (p[i] < q[i]) return -1;
    if (p[i] > q[i]) return 1;
  }
  return p.length - q.length;
}

function adjacency(edges) {
  if (!Array.isArray(edges)) throw new TypeError('edges deve ser um array');
  const adj = new Map();
  for (const e of edges) {
    if (e === null || typeof e !== 'object' || typeof e.from !== 'string' || typeof e.to !== 'string') throw new TypeError('aresta inválida');
    if (typeof e.w !== 'number' || !Number.isFinite(e.w) || e.w < 0) throw new RangeError(`peso inválido: ${e.w}`);
    if (!adj.has(e.from)) adj.set(e.from, []);
    adj.get(e.from).push({ to: e.to, w: e.w });
  }
  return adj;
}

/**
 * Dijkstra com chave (custo, nº de arestas) em ordem lexicográfica; depois, sobre o
 * subgrafo de arestas "justas" (que preservam a chave ótima), escolhe-se o caminho
 * lexicograficamente menor até cada nó.
 */
function run(edges, source) {
  if (typeof source !== 'string') throw new TypeError('source deve ser string');
  const adj = adjacency(edges);
  const key = new Map([[source, { c: 0, h: 0 }]]);
  const done = new Set();
  const heap = new MinHeap((a, b) => a.c - b.c || a.h - b.h, [{ c: 0, h: 0, v: source }]);
  while (heap.size) {
    const { c, h, v: u } = heap.pop();
    if (done.has(u)) continue;
    done.add(u);
    for (const { to: v, w } of adj.get(u) ?? []) {
      if (done.has(v)) continue;
      const nc = c + w;
      const nh = h + 1;
      const cur = key.get(v);
      if (cur === undefined || nc < cur.c || (nc === cur.c && nh < cur.h)) {
        key.set(v, { c: nc, h: nh });
        heap.push({ c: nc, h: nh, v });
      }
    }
  }

  const order = [...done].sort((x, y) => key.get(x).h - key.get(y).h);
  const paths = new Map([[source, [source]]]);
  for (const u of order) {
    const pu = paths.get(u);
    const ku = key.get(u);
    if (pu === undefined) continue;
    for (const { to: v, w } of adj.get(u) ?? []) {
      const kv = key.get(v);
      if (kv === undefined) continue;
      if (kv.h !== ku.h + 1 || ku.c + w !== kv.c) continue;
      const cand = [...pu, v];
      const cur = paths.get(v);
      if (cur === undefined || comparePaths(cand, cur) < 0) paths.set(v, cand);
    }
  }
  return { key, paths };
}

export function shortestPath(edges, source, target) {
  if (typeof target !== 'string') throw new TypeError('target deve ser string');
  const { key, paths } = run(edges, source);
  if (!key.has(target)) return null;
  return { cost: key.get(target).c, path: paths.get(target) };
}

export function distances(edges, source) {
  const { key } = run(edges, source);
  return Object.fromEntries([...key].map(([n, k]) => [n, k.c]));
}

