  const paths = new Map([[source, [source]]]);
  for (const u of order) {
    const pu = paths.get(u);
    const ku = key.get(u);
    if (pu === undefined) continue;
    for (const { to: v, w } of adj.get(u) ?? []) {
      const kv = key.get(v);
      if (kv === undefined) continue;
      if (kv.h !== ku.h + 1 || ku.c + w !== kv.c) continue;
      const cand = [...pu, v];
      const cur = paths.get(v);
      if (cur === undefined || comparePaths(cand, cur) < 0) paths.set(v, cand);
    }
  }
  return { key, paths };
}

export function shortestPath(edges, source, target) {
  if (typeof target !== 'string') throw new TypeError('target deve ser string');
  const { key, paths } = run(edges, source);
  if (!key.has(target)) return null;
  return { cost: key.get(target).c, path: paths.get(target) };
}

export function distances(edges, source) {
  const { key } = run(edges, source);
  return Object.fromEntries([...key].map(([n, k]) => [n, k.c]));
}
